script:
(() => {
  const p = {"css":"/* Issue #849 mock: the stand-in for what Sub 6 adds to src/styles/explorer/broadside.css. Every value here is the round's pick, not ruled. */

/* A plain word in the label column, for a row whose control is a group rather than one input (the sizes). */
.broadside .l-label .l-word {
  font-size: 0.85rem;
  letter-spacing: 0.05em;
  color: var(--ink-brown);
}

/* An untouched islands slider: the thumb sits where the seed's own count would, drawn in the faded ink so it reads as not set. */
.broadside .ledger > input[type="range"].untouched {
  accent-color: var(--ink-faded);
}

/* The type's measured meaning of a count (D14), under the islands rows. */
.broadside .isles-note {
  grid-column: 2 / -1;
  font-family: var(--font-flourish, "Iowan Old Style", "Palatino", Georgia, serif);
  font-style: italic;
  font-size: 0.82rem;
  color: var(--ink-brown);
  margin-top: -0.2rem;
}
.broadside .isles-note[hidden] {
  display: none;
}

/* The stood-down sliders on a counted world: the ground swapped to the cream and a dashed hairline, never opacity, and the inputs stay pressable (`handbook/specs/ui-design.md`, a refusing press). The box is a subgrid so both tracks keep the ledger's one track column. */
.broadside .ledger > .stood {
  grid-column: 1 / -1;
  display: grid;
  grid-template-columns: subgrid;
  gap: 0.5rem 0.6rem;
  align-items: center;
  background: var(--control-cream);
  border: 1px dashed var(--line-tan);
  border-radius: 4px;
  padding: 0.4rem 0.5rem;
}
.broadside .stood > .land-end-min {
  grid-column: 2;
  justify-self: end;
}
.broadside .stood > input[type="range"] {
  grid-column: 3;
  width: 100%;
  min-width: 4rem;
  accent-color: var(--ink-dark);
  margin: 0;
}
.broadside .stood > .land-end-max {
  grid-column: 4;
}
.broadside .stood > .land-readout {
  grid-column: 5;
}
.broadside .stood > .stood-note {
  grid-column: 1 / -1;
  padding: 0 0.6rem;
  font-family: var(--font-flourish, "Iowan Old Style", "Palatino", Georgia, serif);
  font-style: italic;
  font-size: 0.82rem;
  line-height: 1.35;
  color: var(--ink-brown);
}
","rows":"<span class="l-label"><label for="shape">shape</label><a class="fn" href="/glossary/#shape" aria-label="note on the shape">&para;</a></span>
<span class="l-ctl"><select id="shape">
  <option value="">seed's choice</option>
  <optgroup label="the house forms">
    <option value="crescent">the crescent</option>
  </optgroup>
  <optgroup label="after a true chart">
    <option value="texas">Texas</option>
    <option value="japan">Japan</option>
  </optgroup>
</select></span>
<span class="l-label"><label for="isles">islands</label><a class="fn" href="/glossary/#islands" aria-label="note on the islands">&#8214;</a></span>
<span class="land-end land-end-min">few</span>
<input id="isles" type="range" min="2" max="150" step="1">
<span class="land-end land-end-max">many</span>
<span id="isles-readout" class="land-readout"></span>
<span class="l-label"><span class="l-word">sizes</span></span>
<span class="l-ctl seals" role="radiogroup" aria-label="the islands' sizes">
  <label class="check seal">alike <input id="isle-alike" type="radio" name="isle-size"></label>
  <label class="check seal">of every size <input id="isle-every" type="radio" name="isle-size"></label>
</span>
<span id="isles-note" class="isles-note" hidden></span>
","shape":"","isles":null,"size":"alike","stood":false,"typeNote":null};
  const style = document.createElement("style");
  style.textContent = p.css;
  document.head.appendChild(style);
  const ledger = document.querySelector("[aria-labelledby=grp-land] .ledger");
  const bandCtl = document.getElementById("band").closest(".l-ctl");
  const holder = document.createElement("template");
  holder.innerHTML = p.rows;
  bandCtl.after(holder.content);
  document.getElementById("shape").value = p.shape;
  const isles = document.getElementById("isles");
  const readout = document.getElementById("isles-readout");
  if (p.isles === null) { isles.value = "8"; isles.classList.add("untouched"); readout.textContent = "seed's choice"; }
  else { isles.value = String(p.isles); readout.textContent = "about " + p.isles; }
  document.getElementById(p.size === "alike" ? "isle-alike" : "isle-every").checked = true;
  if (p.typeNote) { const n = document.getElementById("isles-note"); n.textContent = p.typeNote; n.hidden = false; }
  if (p.stood) {
    const land = document.getElementById("land");
    const first = land.previousElementSibling.previousElementSibling;
    const box = document.createElement("div");
    box.className = "stood";
    box.setAttribute("role", "group");
    box.setAttribute("aria-label", "held by the count");
    const parts = [];
    for (let el = first; el; el = el.nextElementSibling) parts.push(el);
    for (const el of parts) box.appendChild(el);
    const note = document.createElement("span");
    note.className = "stood-note";
    note.textContent = "the count holds the sea and the shore; set the islands back to the seed's choice to free them";
    box.appendChild(note);
    ledger.appendChild(box);
    document.getElementById("land-readout").textContent = "held";
    document.getElementById("coast-readout").textContent = "held";
  }
  return "seated";
})()

